const body = $input.first().json.body || $input.first().json;
const required = ['executionId', 'enrollmentId', 'stepId'];
const missing = required.filter(f => !body[f]);
if (missing.length > 0) {
  throw new Error('Missing required fields: ' + missing.join(', '));
}
const correlationId = body.correlationId || body.correlation_id || null;
if (!correlationId) {
  throw new Error('Missing correlationId');
}
return [{ json: {
  executionId: body.executionId,
  enrollmentId: body.enrollmentId,
  stepId: body.stepId,
  correlationId: correlationId,
  recipient: body.recipient || body.to,
  subject: body.subject || body.emailSubject,
  message: body.message || body.emailBody || body.content,
  leadId: body.leadId,
  customerId: body.customerId,
  channel: body.channel,
  actionType: body.actionType,
  validatedAt: new Date().toISOString()
} }];

const event = $('2. Validate Event').first().json;
const ctxResp = $input.first().json;
const executions = ctxResp.data || ctxResp.items || [];
const exec = executions.find(e => e.id === event.executionId);
if (!exec) {
  throw new Error('Execution not found: ' + event.executionId);
}
if (exec.enrollmentId !== event.enrollmentId) {
  throw new Error('enrollmentId mismatch');
}
if (exec.stepId !== event.stepId) {
  throw new Error('stepId mismatch');
}
if (exec.status === 'SUCCESS') {
  throw new Error('Execution already completed successfully');
}
if (exec.status === 'RUNNING') {
  throw new Error('Execution already running');
}
return [{ json: {
  ...event,
  executionStatus: exec.status,
  enrollmentStatus: exec.enrollment?.status || 'UNKNOWN',
  isDuplicate: exec.status === 'SUCCESS',
  contextVerified: true
} }];

const data = $input.first().json;
const recipient = data.recipient;
const subject = data.subject;
const message = data.message;
if (!recipient) throw new Error('Missing recipient');
if (!subject) throw new Error('Missing subject');
if (!message) throw new Error('Missing message');
const html = message.replace(/\n/g, '<br/>');
return [{ json: {
  ...data,
  recipientEmail: recipient,
  emailSubject: subject,
  emailHtml: html,
  templateValid: true,
  messageBuiltAt: new Date().toISOString()
} }];

const emailResult = $input.first().json;
const prev = $('5. Build Approved Message').first().json;
const deliveryStatus = emailResult.messageId ? 'SUCCESS' : 'UNKNOWN';
return [{ json: {
  executionId: prev.executionId,
  enrollmentId: prev.enrollmentId,
  stepId: prev.stepId,
  correlationId: prev.correlationId,
  deliveryStatus: deliveryStatus,
  providerMessageId: emailResult.messageId ?? null,
  normalizedAt: new Date().toISOString(),
  error: emailResult.error || null
} }];

const data = $('7. Normalize Delivery Result').first().json;
const idempotencyKey = 'follow-up:' + data.executionId + ':' + data.stepId;
return [{ json: {
  ...data,
  idempotencyKey: idempotencyKey,
  preparedAt: new Date().toISOString()
} }];
